CREATE TABLE IF NOT EXISTS timeline_tracks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,kind TEXT NOT NULL,track_order INTEGER NOT NULL DEFAULT 0,muted BOOLEAN NOT NULL DEFAULT false,locked BOOLEAN NOT NULL DEFAULT false,gain_db REAL NOT NULL DEFAULT 0,metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS timeline_tracks_project_order_idx ON timeline_tracks(project_id,track_order);
CREATE TABLE IF NOT EXISTS timeline_clips(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),track_id UUID NOT NULL REFERENCES timeline_tracks(id) ON DELETE CASCADE,asset_id UUID REFERENCES media_assets(id) ON DELETE SET NULL,scene_id UUID REFERENCES scenes(id) ON DELETE SET NULL,kind TEXT NOT NULL,title TEXT NOT NULL,timeline_start_ms BIGINT NOT NULL DEFAULT 0,timeline_duration_ms BIGINT NOT NULL,source_start_ms BIGINT NOT NULL DEFAULT 0,source_duration_ms BIGINT NOT NULL,playback_rate REAL NOT NULL DEFAULT 1,volume REAL NOT NULL DEFAULT 1,opacity REAL NOT NULL DEFAULT 1,z_index INTEGER NOT NULL DEFAULT 0,transition_in TEXT,transition_out TEXT,metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(timeline_start_ms>=0 AND timeline_duration_ms>0 AND source_start_ms>=0 AND source_duration_ms>0),CHECK(playback_rate>0 AND playback_rate<=4),CHECK(volume>=0 AND volume<=4),CHECK(opacity>=0 AND opacity<=1));
CREATE INDEX IF NOT EXISTS timeline_clips_track_order_idx ON timeline_clips(track_id,z_index,timeline_start_ms);
CREATE TABLE IF NOT EXISTS render_jobs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'queued',profile JSONB NOT NULL,options JSONB NOT NULL DEFAULT '{}',progress REAL NOT NULL DEFAULT 0,stage TEXT NOT NULL DEFAULT 'queued',output_asset_id UUID REFERENCES media_assets(id) ON DELETE SET NULL,output_storage_key TEXT,error TEXT,requested_by TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS render_jobs_project_created_idx ON render_jobs(project_id,created_at DESC);
CREATE INDEX IF NOT EXISTS render_jobs_queue_idx ON render_jobs(status,created_at);
